//! Translations of the strings built in Rust code. The table is generated by `build.rs` from
//! `lang/strings.txt`, the same file the Slint `@tr(...)` strings come from. English is the
//! source language and the default.

use std::sync::atomic::{AtomicU8, Ordering};

include!(concat!(env!("OUT_DIR"), "/i18n_table.rs"));

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Lang {
    En,
    Es,
    De,
    Pl,
    Cs,
    Fr,
}

impl Lang {
    pub const ALL: [Lang; 6] = [Lang::En, Lang::Es, Lang::De, Lang::Pl, Lang::Cs, Lang::Fr];

    pub fn code(self) -> &'static str {
        ["en", "es", "de", "pl", "cs", "fr"][self as usize]
    }

    pub fn native_name(self) -> &'static str {
        ["English", "Español", "Deutsch", "Polski", "Čeština", "Français"][self as usize]
    }

    pub fn from_code(code: &str) -> Lang {
        Lang::ALL.into_iter().find(|l| l.code() == code).unwrap_or(Lang::En)
    }
}

static CURRENT: AtomicU8 = AtomicU8::new(0);

pub fn set_lang(lang: Lang) {
    CURRENT.store(lang as u8, Ordering::Relaxed);
}

pub fn lang() -> Lang {
    Lang::ALL[CURRENT.load(Ordering::Relaxed) as usize]
}

/// Translates `key` (the English text) into the current language.
pub fn t(key: &str) -> String {
    let col = lang() as usize;
    TABLE.iter().find(|r| r[0] == key).map_or(key, |r| r[col]).to_string()
}

/// Translates and substitutes `{0}`, `{1}`, … with `args`.
pub fn tf(key: &str, args: &[&dyn ToString]) -> String {
    let mut s = t(key);
    for (i, a) in args.iter().enumerate() {
        s = s.replace(&format!("{{{i}}}"), &a.to_string());
    }
    s
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn table_is_complete() {
        for r in TABLE {
            assert!(r.iter().all(|c| !c.is_empty()), "{r:?}");
            // Same placeholders in every language.
            for i in 0..4 {
                let p = format!("{{{i}}}");
                assert!(r.iter().all(|c| c.contains(&p) == r[0].contains(&p)), "placeholder {p} in {r:?}");
            }
        }
    }

    #[test]
    fn lookup_and_format() {
        set_lang(Lang::De);
        assert_eq!(tf("Scanning {0} …", &[&"Köln"]), "Scanne Köln …");
        assert_eq!(t("unlisted"), "unlisted");
        set_lang(Lang::En);
    }
}
